//          detail line of a cell (the rule text that used to live only in a title tooltip).

import type { TableModel } from '#/lib/tableModel'

/** The model restricted to the given row heads and column labels (model order is kept). */
export function pickTableModel(m: TableModel, rows: string[], cols: string[]): TableModel {
  const keepRows = new Set(rows)
  const keepCols = new Set(cols)
  const colIdx = m.header.slice(1).flatMap((c, i) => (keepCols.has(c) ? [i] : []))
  return {
    title: m.title,
    header: [m.header[0], ...colIdx.map((i) => m.header[i + 1])],
    rows: m.rows.filter((r) => keepRows.has(r.head)).map((r) => ({ head: r.head, cells: colIdx.map((i) => r.cells[i]) })),
  }
}

/** One-line description of a cell: `[row, column] → rules`, a conflict or an empty (error) cell. */
export function cellDetail(m: TableModel, row: number, col: number): string {
  const r = m.rows[row]
  const c = r?.cells[col]
  if (!r || !c) return ''
  const where = `[${r.head}, ${m.header[col + 1]}] → `
  if (!c.text) return `${where}prázdna bunka (syntaktická chyba)`
  const rules = (c.title || c.text).split('\n').join('; ')
  return where + (c.conflict ? `konflikt: ${rules}` : rules)
}
